def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    # Horizontal notches are the upper/middle segments of vertical channels;
    # bottom singleton stems provide the final segment color.
    bars={}
    for r,row in enumerate(grid):
        for c in range(1,w-1):
            if row[c]==0 and row[c-1]!=0 and row[c-1]==row[c+1]:
                bars.setdefault(c,[]).append((r,row[c-1]))
    for c,marks in bars.items():
        marks.sort()
        # Fill each bar's row and the space above it back to the prior bar.
        for i,(r,color) in enumerate(marks):
            top=marks[i-1][0]+1 if i else 0
            for rr in range(top,r+1):
                out[rr][c]=color
        # Continue below the last notch with the color of the vertical stem.
        stem=next((grid[r][c] for r in range(h-1,-1,-1) if grid[r][c]),None)
        if stem is not None:
            for rr in range(marks[-1][0]+1,h):
                out[rr][c]=stem
    return out
